/**
 * storage.js — where uploaded files live, behind a small adapter.
 *
 * The local adapter writes to a folder outside frontend/ (STORAGE_DIR, default
 * <repo>/storage, gitignored), so nothing uploaded is ever served as a static
 * file: the only way out is a route that checks the session. An Azure Blob
 * adapter with the same four methods replaces it in production.
 *
 *   put(key, buffer)   → void
 *   get(key)           → Buffer | null
 *   remove(key)        → void, quietly when the key is already gone
 *
 * Keys are generated by the server (never from client input) and are checked
 * again here against a strict pattern, so a key can never leave the folder.
 */

import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { ROOT, env } from '../config/env.js';

const KEY = /^[a-z0-9][a-z0-9._-]{0,150}$/;

function assertKey(key) {
  if (typeof key !== 'string' || !KEY.test(key) || key.includes('..')) {
    throw new Error('Invalid storage key.');
  }
}

/** @param {string} dir  an absolute folder */
export function createLocalStorage(dir) {
  const fileOf = (key) => {
    assertKey(key);
    return path.join(dir, key);
  };

  return {
    async put(key, buffer) {
      const file = fileOf(key);
      await mkdir(dir, { recursive: true });
      await writeFile(file, buffer);
    },
    async get(key) {
      try {
        return await readFile(fileOf(key));
      } catch (err) {
        if (err.code === 'ENOENT') return null;
        throw err;
      }
    },
    async remove(key) {
      await rm(fileOf(key), { force: true });
    },
  };
}

/** The process's adapter. */
export function defaultStorage() {
  return createLocalStorage(path.resolve(ROOT, env.STORAGE_DIR ?? 'storage'));
}

/** An in-memory adapter for tests. `files` is exposed to look inside. */
export function createMemoryStorage() {
  const files = new Map();
  return {
    files,
    async put(key, buffer) {
      assertKey(key);
      files.set(key, Buffer.from(buffer));
    },
    async get(key) {
      assertKey(key);
      return files.get(key) ?? null;
    },
    async remove(key) {
      assertKey(key);
      files.delete(key);
    },
  };
}
